#define main edit_program_main
#include EDIT_SOURCE
#undef main
#include <sys/time.h>

static double elapsed(void) {
  struct timeval t;
  gettimeofday(&t, NULL);
  return t.tv_sec * 1000.0 + t.tv_usec / 1000.0;
}
static int compare(const void *a, const void *b) {
  double x = *(const double *)a, y = *(const double *)b;
  return (x > y) - (x < y);
}
int main(int argc, char **argv) {
  if (argc != 4) return 1;
  size_t n = strtoull(argv[1], NULL, 10), width = strtoull(argv[2], NULL, 10);
  int where = atoi(argv[3]);
  edit_state e;
  init_state(&e);
  e.rows = 24;
  e.cols = 80;
  e.n_buffers = e.n_panes = 1;
  e.panes[0].wrap = 2;
  e.panes[0].preferred_col = SIZE_MAX;
  char *text = malloc(n + 1);
  for (size_t i = 0; i < n; i++) text[i] = i % width == width - 1 ? '\n' : i % 6 == 5 ? ' ' : 'a';
  text[n] = 0;
  buffer_set_text(&e.buffers[0], "frames.txt", BUFFER_FILE, text);
  free(text);
  load_grammar(&e);
  e.panes[0].cursor = where == 1 ? n / 2 : where == 2 ? n - 2000 : 0;
  e.panes[0].top = line_start(&e.buffers[0], e.panes[0].cursor);
  freopen("/dev/null", "w", stdout);
  double start = elapsed();
  render(&e);
  double first = elapsed() - start;
  double samples[100];
  for (int i = 0; i < 100; i++) {
    start = elapsed();
    if (where == 2) cmd_up(&e, 0);
    else cmd_down(&e, 0);
    render(&e);
    samples[i] = elapsed() - start;
  }
  qsort(samples, 100, sizeof(double), compare);
  fprintf(stderr, "{\"bytes\":%zu,\"line_bytes\":%zu,\"position\":%d,\"samples\":100,\"cold_ms\":%.3f,\"p50_ms\":%.3f,\"p95_ms\":%.3f,\"p99_ms\":%.3f,\"max_ms\":%.3f}\n",
    n, width, where, first, samples[49], samples[94], samples[98], samples[99]);
  buffers_free(&e);
  return 0;
}
